<?php $mode = $mode ?? 'create'; $product = $product ?? []; $title = $mode === 'edit' ? 'Edit Item' : 'Add Inventory Item'; $itemTypes = $itemTypes ?? \Product::itemTypes(); $category = (string)($product['item_category'] ?? 'Tracker'); $needsIdentifier = in_array($category, ['FLS', 'Cameras', 'Sim cards'], true); ?>
