<script>
const inventoryTypes=<?= json_encode($itemTypes, JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT) ?>,categorySelect=document.getElementById('item-category'),typeSelect=document.getElementById('item-type'),identifierInput=document.getElementById('item-identifier');let preferredType=<?= json_encode($product['item_type'] ?? '') ?>;
function syncInventoryCategory(){const category=categorySelect.value,requiresIdentifier=['FLS','Cameras','Sim cards'].includes(category);identifierInput.required=requiresIdentifier;document.getElementById('identifier-label').innerHTML='Serial number / IMEI (digits only) '+(requiresIdentifier?'<span class="text-danger">*</span>':'<span class="text-secondary fw-normal">(optional)</span>');document.getElementById('identifier-help').textContent=requiresIdentifier?'A unique numeric identifier is required for FLS, camera, and SIM line items.':'Optional for tracker stock. Enter a tracker IMEI only when this row represents one serialized device.';typeSelect.innerHTML='';(inventoryTypes[category]||[]).forEach(value=>{const option=document.createElement('option');option.value=value;option.textContent=value;option.selected=value===preferredType;typeSelect.append(option);});preferredType='';}
categorySelect.addEventListener('change',syncInventoryCategory);syncInventoryCategory();
</script>
